"""flow.gates: generated by the graph.py split (P1)."""

from __future__ import annotations

from typing import Any

from ..runtime import dependencies
from ..state import CfuDesignState



# Answer-only repairs (malformed analysis, conformance oracle or ISA contract)
# have a separate pool and do not consume verification submissions.
DEFAULT_MAX_ANSWER_REPAIRS = 10
DEFAULT_MAX_PREVERIFY_REPAIRS = 2


# Answer-only repairs: a malformed answer artifact (the workload analysis, the
# conformance oracle, the ISA contract) is repaired from a separate pool and does
# not itself count as a candidate submission.
ANSWER_REPAIR_TARGETS = {"analyze_workload", "design_contract", "extend_isa"}


PREPARE_GATE = "prepare_benchmark"


def is_agent_cfu_run(state: CfuDesignState) -> bool:
    """True when this run targets the AgentCfu scaffold rather than a legacy CFU."""
    return bool(state.get("agent_cfu", True))


LADDER_RUNGS = ("hw_build", "hw_conformance", "sw_build", "sim", "cost", "validation_pair")



# A CFU design must show a measurable cycle improvement over the scalar
# reference; 105 means at least 1.05x. Without a floor, a kernel that reverts to
# scalar inside the CFU build (or calls an intrinsic but ignores it) would be
# reported as a successful "acceleration" for a run that is effectively scalar.
MIN_EMBENCH_SPEEDUP_X100 = 105


REQUIRED_GATES = (
    "workload_spec",
    "analysis",
    "isa",
    "implementation_hw",
    "hw_build",
    "hw_conformance",
    "implementation_sw",
    "sw_build",
    "sim",
    "cost",
)


def disabled_gate(gate: Any) -> bool:
    """True when an ablation switch turned this rung off instead of validating it.

    A ``disabled`` gate is recorded (``ok: False``: it was never verified) but is
    out of scope for this run, so it neither fails the run nor forces the
    ``skipped => planned`` honesty rule. Real skips (``--dry-run``, ``--skip-sim``,
    execution disabled) keep that rule and can never produce ``complete``.
    """
    return isinstance(gate, dict) and bool(gate.get("disabled"))


def required_gates(state: CfuDesignState) -> tuple[str, ...]:
    """REQUIRED_GATES minus the rungs an ablation switch disabled."""
    gates = state.get("gates", {}) or {}

    def gate(rung: str) -> Any:
        value = gates.get(rung)
        return value if isinstance(value, dict) else None

    required = []
    for rung in REQUIRED_GATES:
        if disabled_gate(gate(rung)):
            continue
        if rung == "isa" and not state.get("isa_contract", True):
            continue
        if rung == "hw_conformance" and not state.get("require_conformance", True):
            continue
        required.append(rung)
    return tuple(required)


def max_verify_submissions(state: CfuDesignState) -> int:
    """Maximum candidate submissions to the validation ladder (initial included)."""
    return max(1, int(state.get("max_iters", 2) or 2))


def _verify_submissions_left(state: CfuDesignState) -> bool:
    return int(state.get("verify_submissions", 0) or 0) < max_verify_submissions(state)


def max_repairs(state: CfuDesignState) -> int:
    """Maximum repair/optimization rounds after the first verification submission."""
    return max(0, max_verify_submissions(state) - 1)


def answer_repairs_max(state: CfuDesignState) -> int:
    """Repair rounds the answer-only pool (analysis/oracle/spec re-asks) allows."""
    return max(0, int(state.get("max_answer_repairs", DEFAULT_MAX_ANSWER_REPAIRS) or 0))


def preverify_repairs_max(state: CfuDesignState) -> int:
    """Bound implementation reroutes that happen before a candidate is submitted."""
    return max(0, int(state.get("max_preverify_repairs", DEFAULT_MAX_PREVERIFY_REPAIRS) or 0))


def _repairs_left(state: CfuDesignState) -> bool:
    return int(state.get("repairs_used", 0) or 0) < max_repairs(state)


def _answer_repairs_left(state: CfuDesignState) -> bool:
    return int(state.get("answer_repairs_used", 0) or 0) < answer_repairs_max(state)


def _preverify_repairs_left(state: CfuDesignState) -> bool:
    return int(state.get("preverify_repairs_used", 0) or 0) < preverify_repairs_max(state)




# One corrective retry for a rejected delivery before verification: a
# deterministic rejection (SEARCH not found, missing deliverable, rejected
# diagnosis) is a protocol mistake, not a submitted candidate, and must not
# consume a --max-iters verification slot.
DELIVERY_RETRY_MAX = 1


def _rung_gate(state: CfuDesignState, rung: str) -> dict:
    return (state.get("gates", {}) or {}).get(rung, {}) or {}


def _rung_next(state: CfuDesignState, rung: str, default: str) -> str:
    return str(_rung_gate(state, rung).get("next") or default)


def _review_decision(state: CfuDesignState) -> tuple[str, str]:
    gates = state.get("gates", {})
    if isinstance(gates.get(PREPARE_GATE), dict) and gates[PREPARE_GATE].get("ok") is False:
        # Benchmark preparation could not read/copy the workload (for example a
        # C project outside the access policy): the run cannot proceed honestly.
        return "final_report", "failed"
    if state.get("dry_run", False):
        # Dry-run is a planning pass: never claims a measured or complete result.
        return "final_report", "planned"
    profile = gates.get("profile") or {}
    if profile and profile.get("ok") is False and not profile.get("skipped"):
        return "final_report", "failed"
    if gates.get("isa", {}).get("abstain") and not disabled_gate(gates.get("isa")):
        return "final_report", "blocked"
    if not gates.get("workload_spec", {}).get("ok", False):
        return "final_report", "blocked"
    if isinstance(gates.get("analysis"), dict) and not gates["analysis"].get("ok", False):
        return "final_report", "blocked"
    if not gates.get("isa", {}).get("ok", False) and not disabled_gate(gates.get("isa")):
        return "final_report", "blocked"
    if (state.get("ir_features", "off") == "require"
            and not gates.get("ir", {}).get("ok", False)):
        # Explicit IR experiments have their own failure, never an HW/LLM one.
        return "final_report", "failed"
    present = [rung for rung in LADDER_RUNGS if isinstance(gates.get(rung), dict)
               and not disabled_gate(gates.get(rung))]
    executed = [rung for rung in present if not gates[rung].get("skipped")]
    skipped = [rung for rung in present if gates[rung].get("skipped")]
    # A terminal rung failure always reports failed, even when a later rung was
    # never reached because the ladder stopped early.
    if any(not _rung_gate(state, rung).get("ok", False) for rung in executed):
        return "final_report", "failed"
    if not executed:
        return "final_report", "planned"
    if skipped:
        return "final_report", "planned"
    if not all(gates.get(key, {}).get("ok", False) for key in required_gates(state)):
        return "final_report", "blocked"
    if state.get("input_fingerprints"):
        try:
            dependencies.completed_gate_inputs(state)
        except ValueError:
            return "final_report", "blocked"
    return "final_report", "complete"


def _is_complete(state: CfuDesignState) -> bool:
    gates = state.get("gates", {})
    profile = gates.get("profile") or {}
    if profile and profile.get("ok") is False and not profile.get("skipped"):
        return False
    if not all(gates.get(key, {}).get("ok", False) for key in required_gates(state)):
        return False
    if state.get("ir_features", "off") == "require" and not gates.get("ir", {}).get("ok", False):
        return False
    if state.get("input_fingerprints"):
        try:
            dependencies.completed_gate_inputs(state)
        except ValueError:
            return False
    return True
